sealed interface Shape { fun area(): Double }

private class Circle(private val r: Double) : Shape {
    override fun area() = Math.PI * r * r
}

class ShapeFactory private constructor() {
    companion object {
        fun of(kind: String, size: Double): Shape = when (kind) {
            "circle" -> Circle(size)
            else -> throw IllegalArgumentException("unknown shape: $kind")
        }
    }
}
